SELECT

FROM safety_inspection

    1 = 1

        AND project_id = #{param.projectId}


        AND inspection_no LIKE CONCAT('%', #{param.inspectionNo}, '%')


        AND inspection_name LIKE CONCAT('%', #{param.inspectionName}, '%')


        AND inspection_type = #{param.inspectionType}


        AND hazard_level = #{param.hazardLevel}


        AND emergency_level = #{param.emergencyLevel}


        AND rectification_status = #{param.rectificationStatus}


        AND inspector_id = #{param.inspectorId}


        AND inspection_date >= #{param.startDate}


        AND inspection_date <= #{param.endDate}


        AND verification_result = #{param.verificationResult}


ORDER BY inspection_date DESC, create_time DESC

SELECT COUNT(*) as totalInspections, SUM(CASE WHEN inspection_result = 1 THEN 1 ELSE 0 END) as qualifiedCount, SUM(CASE WHEN inspection_result = 2 THEN 1 ELSE 0 END) as unqualifiedCount, SUM(CASE WHEN inspection_result = 3 THEN 1 ELSE 0 END) as basicQualifiedCount, SUM(CASE WHEN risk_level = 1 THEN 1 ELSE 0 END) as lowRiskCount, SUM(CASE WHEN risk_level = 2 THEN 1 ELSE 0 END) as mediumRiskCount, SUM(CASE WHEN risk_level = 3 THEN 1 ELSE 0 END) as highRiskCount, SUM(CASE WHEN risk_level = 4 THEN 1 ELSE 0 END) as extremeRiskCount, SUM(CASE WHEN rectification_status = 1 THEN 1 ELSE 0 END) as rectifiedCount, SUM(CASE WHEN rectification_status = 2 THEN 1 ELSE 0 END) as rectifyingCount, SUM(CASE WHEN rectification_status = 3 THEN 1 ELSE 0 END) as unrectifiedCount FROM safety_inspection
deleted = 0
AND project_id = #{projectId}

SELECT DATE_FORMAT(inspection_date, '%Y-%m') as month, COUNT(*) as totalCount, SUM(CASE WHEN inspection_result = 1 THEN 1 ELSE 0 END) as qualifiedCount, SUM(CASE WHEN inspection_result = 2 THEN 1 ELSE 0 END) as unqualifiedCount FROM safety_inspection
deleted = 0
AND project_id = #{projectId}
AND inspection_date >= #{startDate}
AND inspection_date <= #{endDate}
GROUP BY DATE_FORMAT(inspection_date, '%Y-%m') ORDER BY month DESC LIMIT 12

